 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_pageResult_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_pageResult');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_pageResult'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: fn_pubofrSchdl('${entity.bzProcsNo}','${entity.ldMktTpCd}','${entity.listTpClssCd}','save' );return false; (EL 미해석) · fn_pubofrSchdl('${entity.bzProcsNo}','${entity.ldMktTpCd}','${entity.listTpClssCd}' ,'save');return false; (EL 미해석) · fn_pubofrSchdl('${entity.bzProcsNo}','${entity.ldMktTpCd}','${entity.listTpClssCd}' ,'save' );return false; (EL 미해석) · fn_pubofrSchdl('${entity.bzProcsNo}','${entity.ldMktTpCd}','${entity.listTpClssCd}' ,'save' );return false; (EL 미해석) · fn_prtDepo('${entity.bzProcsNo}','${entity.ldMktTpCd}','${entity.listTpClssCd}','save');return false; (EL 미해석) · fn_prtDepo('${entity.bzProcsNo}' ,'${entity.ldMktTpCd}','${entity.listTpClssCd}','save');return false; (EL 미해석) · fn_prtDepo('${entity.bzProcsNo}','${entity.ldMktTpCd}','${entity.listTpClssCd}','save');return false; (EL 미해석) · fn_prtDepo('${entity.bzProcsNo}','${entity.ldMktTpCd}','${entity.listTpClssCd}' ,'save' );return false; (EL 미해석) · fn_cap('${entity.bzProcsNo}','${entity.ldMktTpCd}','${entity.listTpClssCd}','save');return false; (EL 미해석) · fn_cap('${entity.bzProcsNo}' ,'${entity.ldMktTpCd}','${entity.listTpClssCd}','save');return false; (EL 미해석) · fn_cap('${entity.bzProcsNo}','${entity.ldMktTpCd}','${entity.listTpClssCd}','save');return false; (EL 미해석) · fn_cap('${entity.bzProcsNo}','${entity.ldMktTpCd}','${entity.listTpClssCd}' ,'save' );return false; (EL 미해석) · fn_submit('${entity.bzProcsNo}','${entity.step1DtlStat}|${entity.step2DtlStat}|${entity.step3DtlStat}');return false; (EL 미해석) · fn_noSubmit('${entity.capContnWrtYn}','${entity.fncContnWrtYn}','${entity.stkContnWrtYn}','${entity.instInvstYn}','${entity.cbIsuYn}','${entity.bwIsuYn}','${entity.corpbndIsuCorrYn}','${entity.ventcapCorrYn}','${entity.mergeRelContnWrtYn}','${entity.ldMktTpCd}');return false; (EL 미해석) · fn_submit('${entity.bzProcsNo}','${entity.step1DtlStat}|${entity.step2DtlStat}|${entity.step3DtlStat}');return false; (EL 미해석) · fn_noSubmit('${entity.capContnWrtYn}','${entity.fncContnWrtYn}','${entity.stkContnWrtYn}','${entity.instInvstYn}','${entity.cbIsuYn}','${entity.bwIsuYn}','${entity.corpbndIsuCorrYn}','${entity.ventcapCorrYn}','${entity.mergeRelContnWrtYn}','${entity.ldMktTpCd}');return false; (EL 미해석) · fn_submit('${entity.bzProcsNo}','${entity.step1DtlStat}|${entity.step2DtlStat}|${entity.step3DtlStat}');return false; (EL 미해석) · fn_noSubmit('${entity.capContnWrtYn}','${entity.fncContnWrtYn}','${entity.stkContnWrtYn}','${entity.instInvstYn}','${entity.cbIsuYn}','${entity.bwIsuYn}','${entity.corpbndIsuCorrYn}','${entity.ventcapCorrYn}','${entity.mergeRelContnWrtYn}','${entity.ldMktTpCd}');return false; (EL 미해석) · openAdjReqPop('${entity.bzProcsNo}','120');return false; (EL 미해석) · openAdjReqPop('${entity.bzProcsNo}','120');return false; (EL 미해석) · openAdjReqPop('${entity.bzProcsNo}','120');return false; (EL 미해석) · openAdjReqPop('${entity.bzProcsNo}','120');return false; (EL 미해석) */
        if (r["step1DtlStat"] === '32') { if (typeof scwin.pubofrSchdl === 'function') { await scwin.pubofrSchdl(r["bzProcsNo"], r["ldMktTpCd"], r["listTpClssCd"], "view"); } else { console.error('[sdd] 행 동작 미정의: scwin.pubofrSchdl (열 제출완료)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.pubofrSchdl'); } return; }
        if (r["step1DtlStat"] === '33') { if (typeof scwin.pubofrSchdl === 'function') { await scwin.pubofrSchdl(r["bzProcsNo"], r["ldMktTpCd"], r["listTpClssCd"], "view"); } else { console.error('[sdd] 행 동작 미정의: scwin.pubofrSchdl (열 접수완료)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.pubofrSchdl'); } return; }
        if (r["step1DtlStat"] === '34') { if (typeof scwin.pubofrSchdl === 'function') { await scwin.pubofrSchdl(r["bzProcsNo"], r["ldMktTpCd"], r["listTpClssCd"], "view"); } else { console.error('[sdd] 행 동작 미정의: scwin.pubofrSchdl (열 수정요청중)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.pubofrSchdl'); } return; }
        if (r["step1DtlStat"] === '36') { if (typeof scwin.pubofrSchdl === 'function') { await scwin.pubofrSchdl(r["bzProcsNo"], r["ldMktTpCd"], r["listTpClssCd"], "view"); } else { console.error('[sdd] 행 동작 미정의: scwin.pubofrSchdl (열 수정불가)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.pubofrSchdl'); } return; }
        if (r["step1DtlStat"] === '') { await $c.win.alert('기업일반정보를 먼저 작성해주세요.');return false; return; }
        if (r["step3DtlStat"] === '32') { if (typeof scwin.prtDepo === 'function') { await scwin.prtDepo(r["bzProcsNo"], r["ldMktTpCd"], r["listTpClssCd"], "view"); } else { console.error('[sdd] 행 동작 미정의: scwin.prtDepo (열 제출완료)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.prtDepo'); } return; }
