        if (r["step2DtlStat"] === '32') { if (typeof scwin.cap === 'function') { await scwin.cap(r["bzProcsNo"], r["ldMktTpCd"], r["listTpClssCd"], "view"); } else { console.error('[sdd] 행 동작 미정의: scwin.cap (열 제출완료)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.cap'); } return; }
        if (r["step2DtlStat"] === '33') { if (typeof scwin.cap === 'function') { await scwin.cap(r["bzProcsNo"], r["ldMktTpCd"], r["listTpClssCd"], "view"); } else { console.error('[sdd] 행 동작 미정의: scwin.cap (열 접수완료)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.cap'); } return; }
        if (r["step2DtlStat"] === '34') { if (typeof scwin.cap === 'function') { await scwin.cap(r["bzProcsNo"], r["ldMktTpCd"], r["listTpClssCd"], "view"); } else { console.error('[sdd] 행 동작 미정의: scwin.cap (열 수정요청중)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.cap'); } return; }
        if (r["step2DtlStat"] === '36') { if (typeof scwin.cap === 'function') { await scwin.cap(r["bzProcsNo"], r["ldMktTpCd"], r["listTpClssCd"], "view"); } else { console.error('[sdd] 행 동작 미정의: scwin.cap (열 수정불가)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.cap'); } return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_pageResult.oncellclick' });
    }
};


