/**
 * @method
 * @name scwin.tx_fn_pubofrSchdl
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_pubofrSchdl = async function () {
    const sbmOptions = {
        id: "tx_fn_pubofrSchdl",
        method: "post",
        action: "/listInvstg/listPrelmInvstg.do",
        ref: "dma_pubofrSchdlReq",
        target: "dlt_pageResult=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil51000n2.tx_fn_pubofrSchdl" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

